// Copies ethers + compiled ABIs/bytecode into site/ so the site has no build step and no CDN.
const fs = require("fs");
const path = require("path");
const root = path.join(__dirname, "..");
const pad = require("../build/SqueekPad.json");
const tok = require("../build/SqueekPadToken.json");
const img = require("../build/SqueekPadImages.json");

fs.copyFileSync(path.join(root, "node_modules/ethers/dist/ethers.umd.min.js"), path.join(root, "site/ethers.umd.min.js"));
fs.writeFileSync(path.join(root, "site/contracts.js"),
  "// generated by scripts/export-site.js — do not edit\n" +
  "window.PAD_ABI=" + JSON.stringify(pad.abi) + ";\n" +
  "window.TOKEN_ABI=" + JSON.stringify(tok.abi) + ";\n" +
  "window.PAD_BYTECODE=\"" + pad.bytecode + "\";\n" +
  "window.IMAGES_ABI=" + JSON.stringify(img.abi) + ";\n" +
  "window.IMAGES_BYTECODE=\"" + img.bytecode + "\";\n");
console.log("site/contracts.js + site/ethers.umd.min.js written");
